const SEOUL_CODES = new Set(['11000','11110','11140','11170','11200','11215','11230','11260','11290','11305','11320','11350','11380','11410','11440','11470','11500','11530','11545','11560','11590','11620','11650','11680','11710','11740']);

const raw = $input.first().json;
if (!raw || raw.resultCode !== 200) {
  throw new Error(`온통청년 API error: ${raw && raw.resultCode} ${raw && raw.resultMessage}`);
}
