const pageNum = pagging.pageNum || $('페이지 초기화').first()?.json?.pageNum || $('다음 페이지 이동').first()?.json?.pageNum || 1;
const pageSize = pagging.pageSize || 100;
// TEST MODE: 첫 1페이지만 처리 (검증용). 풀 페이징 활성화 시 아래 줄로 교체.
